    n = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    pq = []

    for i in range(n):
        for j in range(n):
            heappush(pq, (grid[i][j], [(grid[i][j])], i, j))

    while pq:
        value, path, x, y = heappop(pq)
        if len(path) == k:
            return path
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                heappush(pq, (value + grid[nx][ny], path + [grid[nx][ny]], nx, ny))

